#include "portfolio.h"
#include <limits.h>
#include <stdlib.h>
#include <string.h>

static void merge(Asset*a,Asset*t,int l,int m,int r){int i=l,j=m+1,k=l;while(i<=m&&j<=r)t[k++]=strcmp(a[i].symbol,a[j].symbol)<=0?a[i++]:a[j++];while(i<=m)t[k++]=a[i++];while(j<=r)t[k++]=a[j++];for(i=l;i<=r;i++)a[i]=t[i];}
static void msort(Asset*a,Asset*t,int l,int r){int m;if(l>=r)return;m=(l+r)/2;msort(a,t,l,m);msort(a,t,m+1,r);merge(a,t,l,m,r);}
void merge_sort_assets(Asset*a,int n){Asset*t;if(n<2)return;t=malloc((size_t)n*sizeof(*t));if(!t)return;msort(a,t,0,n-1);free(t);}
static void qsorta(Asset*a,int l,int r){int i=l,j=r;Asset p=a[(l+r)/2],x;while(i<=j){while(strcmp(a[i].symbol,p.symbol)<0)i++;while(strcmp(a[j].symbol,p.symbol)>0)j--;if(i<=j){x=a[i];a[i]=a[j];a[j]=x;i++;j--;}}if(l<j)qsorta(a,l,j);if(i<r)qsorta(a,i,r);}
void quick_sort_assets(Asset*a,int n){if(n>1)qsorta(a,0,n-1);}
int binary_search_iterative(const Asset*a,int n,const char*s){int l=0,r=n-1;while(l<=r){int m=(l+r)/2,c=strcmp(a[m].symbol,s);if(!c)return m;if(c<0)l=m+1;else r=m-1;}return -1;}
int binary_search_recursive(const Asset*a,int l,int r,const char*s){int m,c;if(l>r)return -1;m=(l+r)/2;c=strcmp(a[m].symbol,s);if(!c)return m;return c<0?binary_search_recursive(a,m+1,r,s):binary_search_recursive(a,l,m-1,s);}
static int max3(int a,int b,int c){int m=a>b?a:b;return m>c?m:c;}
static int maxsub(const int*a,int l,int r){int m,i,sum=0,left=INT_MIN,right=INT_MIN;if(l==r)return a[l];m=(l+r)/2;for(i=m;i>=l;i--){sum+=a[i];if(sum>left)left=sum;}sum=0;for(i=m+1;i<=r;i++){sum+=a[i];if(sum>right)right=sum;}return max3(maxsub(a,l,m),maxsub(a,m+1,r),left+right);}
int maximum_subarray(const int*a,int n){return n?maxsub(a,0,n-1):0;}
long long fast_power(long long b,unsigned int e){if(!e)return 1;long long h=fast_power(b,e/2);return e%2?h*h*b:h*h;}
int celebrity(const int*m,int n){int c=0,i;for(i=1;i<n;i++)if(m[c*n+i])c=i;for(i=0;i<n;i++)if(i!=c&&(m[c*n+i]||!m[i*n+c]))return -1;return c;}
void matrix_multiply_classic(const int*a,const int*b,int*c,int n){int i,j,k;for(i=0;i<n*n;i++)c[i]=0;for(i=0;i<n;i++)for(k=0;k<n;k++)for(j=0;j<n;j++)c[i*n+j]+=a[i*n+k]*b[k*n+j];}
static void madd(const int*a,const int*b,int*c,int n,int sign){int i;for(i=0;i<n*n;i++)c[i]=a[i]+sign*b[i];}
void matrix_multiply_strassen(const int*a,const int*b,int*c,int n){int h,s,i,j;int *a11,*a12,*a21,*a22,*b11,*b12,*b21,*b22,*m1,*m2,*m3,*m4,*m5,*m6,*m7,*x,*y;if(n<=2||n%2){matrix_multiply_classic(a,b,c,n);return;}h=n/2;s=h*h;a11=calloc((size_t)18*s,sizeof(int));if(!a11){matrix_multiply_classic(a,b,c,n);return;}a12=a11+s;a21=a12+s;a22=a21+s;b11=a22+s;b12=b11+s;b21=b12+s;b22=b21+s;m1=b22+s;m2=m1+s;m3=m2+s;m4=m3+s;m5=m4+s;m6=m5+s;m7=m6+s;x=m7+s;y=x+s;for(i=0;i<h;i++)for(j=0;j<h;j++){a11[i*h+j]=a[i*n+j];a12[i*h+j]=a[i*n+j+h];a21[i*h+j]=a[(i+h)*n+j];a22[i*h+j]=a[(i+h)*n+j+h];b11[i*h+j]=b[i*n+j];b12[i*h+j]=b[i*n+j+h];b21[i*h+j]=b[(i+h)*n+j];b22[i*h+j]=b[(i+h)*n+j+h];}madd(a11,a22,x,h,1);madd(b11,b22,y,h,1);matrix_multiply_strassen(x,y,m1,h);madd(a21,a22,x,h,1);matrix_multiply_strassen(x,b11,m2,h);madd(b12,b22,y,h,-1);matrix_multiply_strassen(a11,y,m3,h);madd(b21,b11,y,h,-1);matrix_multiply_strassen(a22,y,m4,h);madd(a11,a12,x,h,1);matrix_multiply_strassen(x,b22,m5,h);madd(a21,a11,x,h,-1);madd(b11,b12,y,h,1);matrix_multiply_strassen(x,y,m6,h);madd(a12,a22,x,h,-1);madd(b21,b22,y,h,1);matrix_multiply_strassen(x,y,m7,h);for(i=0;i<h;i++)for(j=0;j<h;j++){int z=i*h+j;c[i*n+j]=m1[z]+m4[z]-m5[z]+m7[z];c[i*n+j+h]=m3[z]+m5[z];c[(i+h)*n+j]=m2[z]+m4[z];c[(i+h)*n+j+h]=m1[z]-m2[z]+m3[z]+m6[z];}free(a11);}
int activity_selection(const int*s,const int*f,int n){int order[256],i,j,t,last=-1,count=0;if(n<0||n>256)return -1;for(i=0;i<n;i++)order[i]=i;for(i=0;i<n;i++)for(j=i+1;j<n;j++)if(f[order[j]]<f[order[i]]){t=order[i];order[i]=order[j];order[j]=t;}for(i=0;i<n;i++){int k=order[i];if(last<0||s[k]>=f[last]){count++;last=k;}}return count;}
int interval_partitioning(const int*s,const int*f,int n){int ends[256],order[256],rooms=0,i,j,best,t;if(n>256)return -1;for(i=0;i<n;i++)order[i]=i;for(i=0;i<n;i++)for(j=i+1;j<n;j++)if(s[order[j]]<s[order[i]]){t=order[i];order[i]=order[j];order[j]=t;}for(i=0;i<n;i++){int k=order[i];best=-1;for(j=0;j<rooms;j++)if(ends[j]<=s[k]&&(best<0||ends[j]>ends[best]))best=j;if(best<0)ends[rooms++]=f[k];else ends[best]=f[k];}return rooms;}
int huffman_weighted_path_length(const int*freq,int n){int q[512],m=n,i,a,b,total=0;for(i=0;i<n;i++)q[i]=freq[i];while(m>1){a=0;for(i=1;i<m;i++)if(q[i]<q[a])a=i;int va=q[a];q[a]=q[--m];b=0;for(i=1;i<m;i++)if(q[i]<q[b])b=i;int vb=q[b];q[b]=q[--m];q[m++]=va+vb;total+=va+vb;}return total;}
void dijkstra(const int*g,int n,int src,int*d){int used[128]={0},i,k,v;if(!g||!d||n<=0||n>128||src<0||src>=n)return;for(i=0;i<n;i++)d[i]=INT_MAX/4;d[src]=0;for(k=0;k<n;k++){v=-1;for(i=0;i<n;i++)if(!used[i]&&(v<0||d[i]<d[v]))v=i;if(v<0)break;used[v]=1;for(i=0;i<n;i++)if(g[v*n+i]>0&&d[v]+g[v*n+i]<d[i])d[i]=d[v]+g[v*n+i];}}
int prim_mst(const int*g,int n){int key[128],used[128]={0},i,k,v,total=0;if(!g||n<=0||n>128)return -1;for(i=0;i<n;i++)key[i]=INT_MAX/4;key[0]=0;for(k=0;k<n;k++){v=-1;for(i=0;i<n;i++)if(!used[i]&&(v<0||key[i]<key[v]))v=i;if(v<0||key[v]>=INT_MAX/4)return -1;used[v]=1;total+=key[v];for(i=0;i<n;i++)if(g[v*n+i]>0&&!used[i]&&g[v*n+i]<key[i])key[i]=g[v*n+i];}return total;}
typedef struct{int u,v,w;}Edge;static int root(int*p,int x){while(p[x]!=x){p[x]=p[p[x]];x=p[x];}return x;}
int kruskal_mst(const int*g,int n){Edge e[8192],t;int m=0,i,j,k,p[128],total=0,c=0;if(!g||n<=0||n>128)return -1;for(i=0;i<n;i++)for(j=i+1;j<n;j++)if(g[i*n+j]>0)e[m++]=(Edge){i,j,g[i*n+j]};for(i=0;i<m;i++)for(j=i+1;j<m;j++)if(e[j].w<e[i].w){t=e[i];e[i]=e[j];e[j]=t;}for(i=0;i<n;i++)p[i]=i;for(k=0;k<m&&c<n-1;k++){int a=root(p,e[k].u),b=root(p,e[k].v);if(a!=b){p[a]=b;total+=e[k].w;c++;}}return c==n-1?total:-1;}
int knapsack01(const int*w,const int*v,int n,int cap){int*dp=calloc((size_t)cap+1,sizeof(int));int i,c,ans;if(!dp)return 0;for(i=0;i<n;i++)for(c=cap;c>=w[i];c--)if(dp[c-w[i]]+v[i]>dp[c])dp[c]=dp[c-w[i]]+v[i];ans=dp[cap];free(dp);return ans;}
long long matrix_chain(const int*d,int n){long long dp[64][64]={0};int len,i,j,k;if(!d||n<2||n>64)return -1;for(len=2;len<n;len++)for(i=1;i<n-len+1;i++){j=i+len-1;dp[i][j]=LLONG_MAX/4;for(k=i;k<j;k++){long long q=dp[i][k]+dp[k+1][j]+(long long)d[i-1]*d[k]*d[j];if(q<dp[i][j])dp[i][j]=q;}}return dp[1][n-1];}
int lcs_length(const char*a,const char*b){int n=(int)strlen(a),m=(int)strlen(b),i,j;int*dp=calloc((size_t)(m+1),sizeof(int));int*pr=calloc((size_t)(m+1),sizeof(int));if(!dp||!pr){free(dp);free(pr);return 0;}for(i=1;i<=n;i++){for(j=1;j<=m;j++)dp[j]=a[i-1]==b[j-1]?pr[j-1]+1:(pr[j]>dp[j-1]?pr[j]:dp[j-1]);int*t=pr;pr=dp;dp=t;}i=pr[m];free(dp);free(pr);return i;}
int optimal_bst_cost(const int*f,int n){int dp[64][64]={0},sum[65]={0},len,i,j,r,best;if(!f||n<0||n>64)return -1;for(i=0;i<n;i++){dp[i][i]=f[i];sum[i+1]=sum[i]+f[i];}for(len=2;len<=n;len++)for(i=0;i+len<=n;i++){j=i+len-1;best=INT_MAX/4;for(r=i;r<=j;r++){int v=(r>i?dp[i][r-1]:0)+(r<j?dp[r+1][j]:0);if(v<best)best=v;}dp[i][j]=best+sum[j+1]-sum[i];}return n?dp[0][n-1]:0;}
int bellman_ford(const int*e,int ec,int v,int src,int*d){int i,j,u,w,to;for(i=0;i<v;i++)d[i]=INT_MAX/4;d[src]=0;for(i=1;i<v;i++)for(j=0;j<ec;j++){u=e[3*j];to=e[3*j+1];w=e[3*j+2];if(d[u]<INT_MAX/4&&d[u]+w<d[to])d[to]=d[u]+w;}for(j=0;j<ec;j++){u=e[3*j];to=e[3*j+1];w=e[3*j+2];if(d[u]<INT_MAX/4&&d[u]+w<d[to])return 0;}return 1;}
void floyd_warshall(int*g,int n){int i,j,k;for(k=0;k<n;k++)for(i=0;i<n;i++)for(j=0;j<n;j++)if(g[i*n+k]<INT_MAX/4&&g[k*n+j]<INT_MAX/4&&g[i*n+k]+g[k*n+j]<g[i*n+j])g[i*n+j]=g[i*n+k]+g[k*n+j];}
static int tsprec(const int*g,int n,int pos,int mask,int all,int memo[12][4096]){int i,best=INT_MAX/4,v;if(mask==all)return g[pos*n];if(memo[pos][mask]>=0)return memo[pos][mask];for(i=1;i<n;i++)if(!(mask&(1<<i))){v=g[pos*n+i]+tsprec(g,n,i,mask|(1<<i),all,memo);if(v<best)best=v;}return memo[pos][mask]=best;}
int tsp_bounded(const int*g,int n){int memo[12][4096],i,j;if(n<2||n>12)return -1;for(i=0;i<12;i++)for(j=0;j<4096;j++)memo[i][j]=-1;return tsprec(g,n,0,1,(1<<n)-1,memo);}
static int nqrec(int n,int row,unsigned long long col,unsigned long long d1,unsigned long long d2){unsigned long long avail,bit,mask=(1ULL<<n)-1;int c=0;if(row==n)return 1;avail=mask&~(col|d1|d2);while(avail){bit=avail&(~avail+1);avail-=bit;c+=nqrec(n,row+1,col|bit,((d1|bit)<<1)&mask,(d2|bit)>>1);}return c;}
int nqueens_count(int n){return n>0&&n<16?nqrec(n,0,0,0,0):0;}
int subset_sum(const int*a,int n,int target){unsigned char*dp;if(target<0)return 0;dp=calloc((size_t)target+1,1);if(!dp)return 0;dp[0]=1;for(int i=0;i<n;i++)for(int s=target;s>=a[i];s--)if(dp[s-a[i]])dp[s]=1;int ans=dp[target];free(dp);return ans;}
int ford_fulkerson(const int*cap,int n,int s,int t){if(!cap||n<=0||n>128||s<0||s>=n||t<0||t>=n||s==t)return 0;int*r=malloc((size_t)n*n*sizeof(int));int parent[128],q[128],flow=0,i;if(!r)return 0;memcpy(r,cap,(size_t)n*n*sizeof(int));for(;;){int h=0,z=0,seen[128]={0};q[z++]=s;seen[s]=1;parent[s]=-1;while(h<z&&!seen[t]){int u=q[h++];for(i=0;i<n;i++)if(!seen[i]&&r[u*n+i]>0){seen[i]=1;parent[i]=u;q[z++]=i;}}if(!seen[t])break;int add=INT_MAX;for(i=t;i!=s;i=parent[i])if(r[parent[i]*n+i]<add)add=r[parent[i]*n+i];for(i=t;i!=s;i=parent[i]){r[parent[i]*n+i]-=add;r[i*n+parent[i]]+=add;}flow+=add;}free(r);return flow;}
static int bpmrec(const int*g,int l,int rn,int u,int*seen,int*match){int v;for(v=0;v<rn;v++)if(g[u*rn+v]&&!seen[v]){seen[v]=1;if(match[v]<0||bpmrec(g,l,rn,match[v],seen,match)){match[v]=u;return 1;}}return 0;}
int bipartite_matching(const int*g,int ln,int rn){int match[128],seen[128],u,c=0;if(!g||ln<0||rn<0||ln>128||rn>128)return -1;for(u=0;u<rn;u++)match[u]=-1;for(u=0;u<ln;u++){memset(seen,0,(size_t)rn*sizeof(int));c+=bpmrec(g,ln,rn,u,seen,match);}return c;}
static long long egcd(long long a,long long b,long long*x,long long*y){if(!b){*x=1;*y=0;return a;}long long x1,y1,g=egcd(b,a%b,&x1,&y1);*x=y1;*y=x1-(a/b)*y1;return g;}
long long crt(const long long*r,const long long*m,int n){long long M=1,res=0,x,y;int i;for(i=0;i<n;i++)M*=m[i];for(i=0;i<n;i++){long long Mi=M/m[i];if(egcd(Mi,m[i],&x,&y)!=1)return -1;res=(res+r[i]*Mi*x)%M;}return (res%M+M)%M;}
int naive_match_count(const char*t,const char*p){int n=(int)strlen(t),m=(int)strlen(p),i,c=0;if(!m)return n+1;for(i=0;i+m<=n;i++)if(!strncmp(t+i,p,(size_t)m))c++;return c;}
int rabin_karp_count(const char*t,const char*p){int n=(int)strlen(t),m=(int)strlen(p),i,c=0;long long hp=0,ht=0,pow=1,base=257,mod=1000000007;if(!m)return n+1;if(m>n)return 0;for(i=0;i<m;i++){hp=(hp*base+(unsigned char)p[i])%mod;ht=(ht*base+(unsigned char)t[i])%mod;if(i<m-1)pow=pow*base%mod;}for(i=0;i+m<=n;i++){if(hp==ht&&!strncmp(t+i,p,(size_t)m))c++;if(i+m<n){ht=(ht-(unsigned char)t[i]*pow)%mod;if(ht<0)ht+=mod;ht=(ht*base+(unsigned char)t[i+m])%mod;}}return c;}
int finite_automaton_count(const char*t,const char*p){int m=(int)strlen(p),state=0,c=0,i,q,ch,k;if(!m)return (int)strlen(t)+1;int *delta=malloc((size_t)(m+1)*256*sizeof(int));if(!delta)return 0;for(q=0;q<=m;q++)for(ch=0;ch<256;ch++){int ns=q<m?q+1:m;while(ns>0){int ok=1;for(k=0;k<ns;k++){int pos=q-ns+1+k;unsigned char actual=(pos==q)?(unsigned char)ch:(pos>=0&&pos<q?(unsigned char)p[pos]:0);if(pos<0||actual!=(unsigned char)p[k]){ok=0;break;}}if(ok)break;ns--;}delta[q*256+ch]=ns;}for(i=0;t[i];i++){state=delta[state*256+(unsigned char)t[i]];if(state==m)c++;}free(delta);return c;}
int kmp_count(const char*t,const char*p){int m=(int)strlen(p),*lps,i=1,j=0,c=0;if(!m)return (int)strlen(t)+1;lps=calloc((size_t)m,sizeof(int));if(!lps)return 0;while(i<m){if(p[i]==p[j])lps[i++]=++j;else if(j)j=lps[j-1];else lps[i++]=0;}i=0;j=0;while(t[i]){if(t[i]==p[j]){i++;j++;if(j==m){c++;j=lps[j-1];}}else if(j)j=lps[j-1];else i++;}free(lps);return c;}
